function redactEntry(key: string, value: unknown): [string, SafeValue][] {
  if (FORBIDDEN_KEYS.has(key.toLowerCase())) return [];
  if (typeof value === 'string') return scalarEntry(key, value);
  if (isNumberOrBoolean(value)) return [[key, value]];
  if (isPlainObject(value)) return redactNested(key, value);
  if (Array.isArray(value)) return safeArrayEntry(key, value);
  return [];
}

